from __future__ import annotations
from fractions import Fraction

def exact_uniform_guesswork(base: int, dimension: int) -> dict[str, Fraction | int]:
    if base < 1 or dimension < 0:
        raise ValueError("Require base >= 1 and dimension >= 0")
    n = base ** dimension
    mean = Fraction(n + 1, 2)
    second = Fraction((n + 1) * (2 * n + 1), 6)
    variance = Fraction(n * n - 1, 12)
    return {"N": n, "mean": mean, "second": second, "variance": variance,
            "mean_over_N": mean / n, "second_over_N2": second / n**2,
            "variance_over_N2": variance / n**2,
            "cv_squared": variance / mean**2}

if __name__ == "__main__":
    for k in (1, 2, 4, 8, 12):
        print(k, exact_uniform_guesswork(2, k))

from __future__ import annotations
from fractions import Fraction

def audit(candidate_count: int) -> tuple[Fraction, Fraction, bool]:
    if candidate_count < 1:
        raise ValueError("candidate_count must be positive")
    direct_mean = Fraction(sum(range(1, candidate_count + 1)), candidate_count)
    direct_second = Fraction(sum(j*j for j in range(1, candidate_count + 1)), candidate_count)
    expected_mean = Fraction(candidate_count + 1, 2)
    expected_second = Fraction((candidate_count + 1)*(2*candidate_count + 1), 6)
    return direct_mean, direct_second, (direct_mean, direct_second) == (expected_mean, expected_second)

if __name__ == "__main__":
    for n in (1, 2, 16, 100):
        print(n, audit(n))

from __future__ import annotations
import random

def simulate(candidate_count: int, trials: int, seed: int = 20260715) -> tuple[float, float]:
    if candidate_count < 1 or trials < 1:
        raise ValueError("arguments must be positive")
    rng = random.Random(seed)
    total = total2 = 0
    for _ in range(trials):
        rank = rng.randint(1, candidate_count)
        total += rank
        total2 += rank * rank
    return total/(trials*candidate_count), total2/(trials*candidate_count**2)

if __name__ == "__main__":
    print(simulate(4096, 200_000))

